    titleEn: "In Conversation with a Photographer Who Avoids Tourist Crowds",
    sourceGroup: "unit",
    sourceLabel: "Unit 6: Places (Đô thị & Du lịch)",
    unitId: "unit_6_places_(đô_thị_and_du_lịch)",
